      "phrases": [
        {
          "id": "C1-01",
          "zh": "爱从何处 降临人间 无声却很明亮"
        },
        {
          "id": "C1-02",
          "zh": "按着胸口 问自己 听心跳回答"
        },
        {
          "id": "C1-03",
          "zh": "橱窗里的假货 我一眼都不看"
        },
        {
          "id": "C1-04",
          "zh": "真正的爱我要 亲手去找到"
        },
        {
          "id": "C1-05",
          "zh": "人海里我一直 在找你身影"
        }
      ]
    }
